function ruleText(r){if(lang==='en')return r.message;return faRules[r.id.split(':')[1]]||'برای این انتخاب، الزام فنی منبع باید بررسی شود.';}
function showDetails(o){modal=()=>{const box=el('div');box.append(el('h3',o.sku),el('p',o.description,'evidence'));const table=el('table');for(const[k,v]of Object.entries(o.attributes||{})){if(v==null)continue;const tr=el('tr');tr.append(el('td',k),el('td',String(v),'code'));table.append(tr);}box.append(table,el('p',t('evidenceNote'),'small muted'),evidence(o.evidence));return box;};renderModal(t('evidenceTitle'));}
function renderModal(title){const overlay=el('div',null,'dialog-backdrop');const box=el('section',null,'dialog');box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label',title);const header=el('div',null,'dialog-header');const close=btn('×',()=>overlay.remove(),'close');close.setAttribute('aria-label',t('close'));header.append(el('h2',title),close);box.append(header,modal());overlay.append(box);document.body.append(overlay);close.focus();overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove();});overlay.addEventListener('keydown',e=>{if(e.key==='Escape')overlay.remove();if(e.key==='Tab'){const f=[...box.querySelectorAll('button,a,input,select,summary,[tabindex="0"]')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}});}
function coverageModal(){modal=()=>{const d=el('div');d.append(el('p',t('coverageBody')),el('p',`${data.models.length} ${lang==='fa'?'پلتفرم':'platforms'} · ${data.rules.length} ${lang==='fa'?'قاعده اجرایی':'executable rules'} · ${data.options.length} ${lang==='fa'?'گزینه منبع‌دار':'source-linked entries'}`,'small muted'));return d;};renderModal(t('coverageTitle'));}
function layout(){app.replaceChildren();document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.title=lang==='fa'?'آریا | پیکربندی سرور HPE':'ARIA | HPE Configuration Studio';const header=el('header'),brand=el('div',null,'brand');const wm=el('span','ARIA','wordmark');wm.dir='ltr';brand.append(wm);const label=el('div');label.append(el('small','SERVER CONFIGURATION'),el('b',t('brand')));brand.append(label);const actions=el('div',null,'header-actions');actions.append(el('span',t('private'),'local-tag'));const language=el('button',lang==='fa'?'English':'فارسی','language');language.onclick=()=>{lang=lang==='fa'?'en':'fa';render();};actions.append(language);header.append(brand,actions);const top=el('div',null,'topline'),title=el('div');title.append(el('p','ARIA / INFRASTRUCTURE STUDIO','eyebrow'),el('h1',t('title')));top.append(title,el('span',t('reviewRequired'),'review-label'));const main=el('main'),nav=el('nav',null,'stepper');nav.setAttribute('aria-label',lang==='fa'?'مراحل پیکربندی':'Configuration steps');for(let n=1;n<=4;n++){const b=el('button',null,'step '+(state.step===n?'current':state.step>n?'done':''));b.append(el('span',state.step>n?'✓':number(n)),document.createTextNode(t('step'+n)));b.disabled=n>2&&!state.model_id;if(n===state.step)b.setAttribute('aria-current','step');b.onclick=()=>go(n);nav.append(b);}main.append(nav);const content=el('section',null,'page');main.append(content);const footer=el('footer');footer.append(el('span',t('footer')),el('span',t('independent')));app.append(header,top,main,footer);return content;}
function workPage(root){const lead=el('div',null,'lead'),left=el('div');left.append(el('h2',t('workloadTitle')),el('p',t('workloadSub')));lead.append(left);root.append(lead);const grid=el('div',null,'workloads');for(const key of ['virtualization','database','business','storage','ai_inference','ai_training']){const b=el('button',null,'workload '+(state.workload===key?'selected':''));b.setAttribute('aria-pressed',state.workload===key);b.append(icon(key));const text=el('div');text.append(el('h3',key==='storage'?(lang==='fa'?'ذخیره‌سازی و پشتیبان‌گیری':'Storage & backup'):t(key)),el('p',t(key+'Desc')));b.append(text);if(state.workload===key)b.append(el('span','✓','selected-dot'));b.onclick=()=>change(()=>{state.workload=key;if(key==='database')state.requirements.ramGB=256;if(key==='business')state.requirements.ramGB=64;if(key==='virtualization')state.requirements.ramGB=Math.ceil(state.requirements.vms*state.requirements.ramPerVM*1.2);});grid.append(b);}root.append(grid);const sizing=el('div',null,'sizing'),intro=el('div');intro.append(el('h3',t('sizeTitle')),el('p',t('sizeSub'),'small muted'));const fs=el('div',null,'sizing-fields');const req=state.requirements;if(state.workload==='virtualization'){fs.append(field(t('vmCount'),req.vms,v=>change(()=>{req.vms=v;req.ramGB=Math.ceil(req.vms*req.ramPerVM*1.2);})),field(t('vmRAM'),req.ramPerVM,v=>change(()=>{req.ramPerVM=v;req.ramGB=Math.ceil(req.vms*req.ramPerVM*1.2);})),field(t('ramTarget'),req.ramGB,v=>req.ramGB=v));intro.append(el('p',t('headroom'),'small muted'));}else fs.append(field(t('ramTarget'),req.ramGB,v=>req.ramGB=v),field(t('coreTarget'),req.cores,v=>req.cores=v),field(t(state.workload.startsWith('ai')?'gpuTarget':'storageTarget'),state.workload.startsWith('ai')?req.gpuGB:req.storageTB,v=>{if(state.workload.startsWith('ai'))req.gpuGB=v;else req.storageTB=v;}));sizing.append(intro,fs);root.append(sizing);const bottom=el('div',null,'bottom-action');bottom.append(el('p',guidance(),'advice-strip'),arrowButton(t('findServers'),()=>go(2)));root.append(bottom);}
function guidance(){return t(state.workload==='virtualization'?'tipVirtual':state.workload==='database'?'tipDatabase':state.workload==='business'?'tipBusiness':state.workload==='storage'?'tipStorage':'tipAI');}
function serversPage(root){root.append(leadBlock(t('recommendTitle')+' '+t(state.workload),t('recommendSub')));const grid=el('div',null,'server-grid');const ranked=recommend(data,state.workload).map(m=>({...m,...workloadLimits(m,data,state.requirements,state.workload)})).sort((a,b)=>Boolean(a.blockers.length)-Boolean(b.blockers.length));ranked.forEach((m,index)=>{const card=el('article',null,'server '+(index===0&&!m.blockers.length?'recommended':''));card.append(el('div',m.blockers.length?t('targetExceeds'):index===0?t('recommended'):t('alternative'),'server-label'),el('div',m.short.replace(' Gen11',''),'server-code'),el('p','HPE ProLiant · Gen11','server-gen'));const facts=el('div',null,'server-facts');for(const [value,label]of [[m.id==='16912'?t('tower'):(m.id==='16910'?'1U':'2U'),t('height')],[number(2),t('socket')],[number(m.dimms),t('dimms')],[t(m.id==='16913'?'gpuFocus':m.id==='16910'?'density':m.id==='16912'?'office':'expansion'),t('focus')]]){const d=el('div');d.append(el('strong',value),el('small',label));facts.append(d);}const ul=el('ul');ul.append(el('li',t(m.id==='16913'?'dl380aNote':m.id==='16910'?'dl360Note':m.id==='16912'?'ml350Note':'dl380Note')),el('li',t('verifiedSource')));if(m.blockers.length)ul.append(el('li',t('targetExceedsNote')));const choose=btn(t('selectServer'),()=>chooseModel(m),index===0?'primary':'');choose.disabled=Boolean(m.blockers.length);card.append(facts,ul,choose);grid.append(card);});root.append(grid,el('div',t('serverWarning'),'notice'),btn(t('back'),()=>go(1),'ghost'));}
function leadBlock(title,sub){const l=el('div',null,'lead'),d=el('div');d.append(el('h2',title),el('p',sub));l.append(d);return l;}
function chooseModel(m){if(state.model_id&&state.model_id!==m.id&&Object.keys(state.selected).length&&!confirm(t('confirmModel')))return;state={...state,model_id:m.id,chassis:m.chassis[0],selected:{},cpuQty:m.id==='16913'?2:1,memoryQty:8,psuQty:m.id==='16913'?4:2,step:3};category='cpu';query='';page=0;render();window.scrollTo({top:0,behavior:'smooth'});}
function partTitle(o){const a=o.attributes;switch(o.category){case'cpu':return `Intel Xeon ${a.model} · ${a.cores} ${lang==='fa'?'هسته':'cores'}`;case'memory':return `${a.capacity_gb} GB · DDR5-${a.speed_mts} · ${a.type||'DIMM'}`;case'storage':return `${a.capacity_gb>=1000?a.capacity_gb/1000+' TB':a.capacity_gb+' GB'} · ${a.protocol} · ${a.form||'SSD'} · ${(o.description.match(/(?:PM|CM|CD|PE|PS)\d+[A-Za-z0-9]*|Multi Vendor/)||[''])[0]}`;case'gpu':return o.description.replace('NVIDIA ','').replace(o.sku,'').trim();case'psu':return o.description.replace('HPE ','').replace(o.sku,'').replace('Hot Plug Low Halogen Power Supply Kit','').trim();default:return o.description===o.sku?o.sku:o.description.replace('HPE ProLiant ','').replace('HPE ','').replace(o.sku,'').trim();}}
function changeQuantity(key,value){const n=Math.round(value);if(n<1||n>128)return;state[key]=n;page=0;render();if(directConflicts(state,data).length||activeFindings(state,data).some(r=>r.status==='conflict'))toast(t('keptConflicts'));}
function componentPage(root){const lead=leadBlock(t('partsTitle'),t('partsSub'));lead.append(btn(t('change')+' '+t('step2'),()=>go(2),'ghost'));root.append(lead);const meta=el('div',null,'build-meta');meta.append(field(t('chassis'),state.chassis,v=>change(()=>state.chassis=v),{type:'text',options:model().chassis.map(x=>[x,x])}),field(t('voltage'),state.inputV,v=>change(()=>state.inputV=v),{min:100,max:277}),field(t('thermal'),state.cooling,v=>change(()=>state.cooling=v),{type:'text',options:[['air',t('air')],['liquid',t('liquid')]]}));root.append(meta);const workspace=el('div',null,'workspace'),nav=el('nav',null,'category-nav');nav.setAttribute('aria-label',t('category'));for(const cat of CATEGORIES){const b=el('button',null,category===cat?'current':'');b.append(icon(cat),el('span',t(cat)));if(state.selected[cat]?.length)b.append(el('span',number(state.selected[cat].length),'count'));b.onclick=()=>{category=cat;page=0;query='';render();};nav.append(b);}const main=el('div',null,'component-main');workspace.append(nav,main,summaryPanel());root.append(workspace);renderParts(main);}
function renderParts(root){root.replaceChildren();const top=el('div',null,'component-top');const row=el('div',null,'row');row.append(el('h2',t(category)));if(state.selected[category]?.length)row.append(btn(t('remove'),()=>change(()=>delete state.selected[category]),'compact ghost'));top.append(row,el('p',t(category+'Help'),'category-help'));const tools=el('div',null,'component-tools');const search=el('input');search.className='search';search.placeholder=t('search');search.setAttribute('aria-label',t('search'));search.value=query;search.oninput=()=>{const pos=search.selectionStart;query=search.value;page=0;renderParts(root);const inp=root.querySelector('.search');inp.focus();inp.setSelectionRange(pos,pos);};tools.append(search);const key={cpu:'cpuQty',memory:'memoryQty',storage:'driveQty',gpu:'gpuQty',psu:'psuQty'}[category];if(key)tools.append(field(t('qty'),state[key],v=>changeQuantity(key,v),{max:category==='cpu'?2:category==='psu'?4:category==='gpu'?8:128}));top.append(tools);if(category==='storage')top.append(field(t('raid'),state.raid,v=>change(()=>state.raid=v),{type:'text',options:['0','1','5','6','10'].map(x=>[x,'RAID '+x])}));if(!['cpu','memory','storage','psu'].includes(category)&&!(category==='gpu'&&state.model_id==='16913'))top.append(el('p',t('optional'),'small muted'));root.append(top);const all=data.options.filter(o=>o.model_id===state.model_id&&o.category===category);const checked=all.map(o=>({o,check:optionCheck(state,data,o)}));const visible=checked.filter(({o,check})=>!check.hidden&&(!query||(o.description+' '+o.sku).toLowerCase().includes(query.toLowerCase())));root.append(el('p',`${number(visible.length)} ${t('visibleOptions')} · ${number(checked.filter(x=>x.check.hidden).length)} ${t('hiddenCount')}`,'small muted'));
 const currentBad=checked.filter(({o,check})=>check.hidden&&state.selected[category]?.includes(o.sku));if(currentBad.length){const note=el('div',null,'notice');note.append(el('b',t('incompatibleSelected')),el('p',currentBad.map(x=>x.o.sku).join(', ')),btn(t('remove'),()=>change(()=>delete state.selected[category]),'compact'));root.append(note);}const list=el('div',null,'part-list');const start=page*8;for(const {o,check}of visible.slice(start,start+8)){const active=state.selected[category]?.includes(o.sku);const card=el('article',null,'part '+(active?'selected':''));const content=el('div');content.append(el('div',partTitle(o),'part-title'),el('span',o.sku,'part-sku'));const chips=el('div',null,'part-specs');if(o.attributes.tdp_w)chips.append(el('span',`${o.attributes.tdp_w} W TDP`,'chip'));if(o.attributes.rank)chips.append(el('span',`${o.attributes.rank}R ×${o.attributes.width}`,'chip'));if(o.attributes.mount)chips.append(el('span',o.attributes.mount,'chip'));chips.append(el('span',t('listed'),'chip'),el('span',t('reviewRequired'),'chip amber'));content.append(chips);if(check.requirements.length)content.append(el('p',t('needsKit'),'part-note'));const acts=el('div',null,'part-actions');if(active&&!['cpu','memory','storage','gpu','psu'].includes(o.category))acts.append(field(t('qty'),quantity(state,o),v=>change(()=>{state.extraQty??={};state.extraQty[o.sku]=Math.round(v);}),{max:16}));acts.append(btn(active?t('selected'):t('select'),()=>selectPart(o),active?'dark':'primary'));const details=el('button',t('details'),'technical-toggle');details.onclick=()=>showDetails(o);acts.append(details);card.append(content,acts);list.append(card);}if(!visible.length){const empty=el('div',null,'empty');empty.append(el('h3',t('noOptions')),el('p',t('noOptionsBody')));if(category==='backplane')empty.append(el('p',t('baseCage')));list.append(empty);}root.append(list);if(visible.length>8){const pager=el('div',null,'pagination');const prev=btn(t('previous'),()=>{page--;renderParts(root);},'compact');prev.disabled=page===0;const next=btn(t('nextPage'),()=>{page++;renderParts(root);},'compact');next.disabled=start+8>=visible.length;pager.append(prev,el('span',`${number(page+1)} / ${number(Math.ceil(visible.length/8))}`,'small muted'),next);root.append(pager);}root.append(requirementsPanel(),el('div',t('coverageNotice'),'notice'));const action=el('div',null,'bottom-action');const index=CATEGORIES.indexOf(category);if(index<CATEGORIES.length-1)action.append(arrowButton(t('next')+' · '+t(CATEGORIES[index+1]),()=>{category=CATEGORIES[index+1];query='';page=0;render();}));else action.append(arrowButton(t('continueReview'),()=>go(4)));root.append(action);}
function selectPart(o){const check=optionCheck(state,data,o);if(check.hidden){toast(t('selectionConflict'));return;}const multi=['riser','cooling','kits'].includes(o.category);if(multi){const existing=state.selected[o.category]||[];state.selected[o.category]=existing.includes(o.sku)?existing:existing.concat(o.sku);}else state.selected[o.category]=[o.sku];render();toast(t('added'));}
function requirementsPanel(){const panel=el('section',null,'relations');panel.append(el('h3',t('requirements')));const needs=requiredKits(state,data);if(!needs.length){panel.append(el('p',t('noKits'),'small muted'));return panel;}for(const need of needs){const row=el('div',null,'relation-item'),text=el('div');text.append(el('p',ruleText(need.rule)),el('span',(need.any.length>1?t('chooseOne')+': ':'')+need.any.join(' / '),'part-sku'));const controls=el('div',null,'row wrap');for(const sku of need.any){const opt=data.options.find(o=>o.model_id===state.model_id&&o.sku===sku);if(opt)controls.append(btn(t('addKit')+' '+sku,()=>selectPart(opt),'compact'));}const sourceBtn=el('button',t('whyNeeded'),'info-link');sourceBtn.onclick=()=>showDetails({sku:need.any.join(' / '),description:ruleText(need.rule),attributes:{},evidence:need.rule.evidence});text.append(sourceBtn);row.append(text,controls);panel.append(row);}return panel;}
function summaryPanel(){const s=stats(state,data),panel=el('aside',null,'summary'),head=el('div',null,'summary-head');head.append(el('p',t('buildSummary'),'small'),el('div',model().short,'server-code'),el('small',state.chassis+' · '+t(state.workload)));const metrics=el('div',null,'summary-metrics');for(const[value,unit,label]of [[s.cores,'',t('physicalCores')],[s.memory,'GB',t('installedRAM')],[s.usable==null?'—':s.usable/1000,'TB',t('usableStorage')],[s.gpuMemory||'—','GB',t('gpuMemory')]]){const m=el('div');m.append(el('strong',`${typeof value==='number'?number(value):value} ${unit}`),el('small',label));metrics.append(m);}const items=el('div',null,'summary-items');for(const cat of ['cpu','memory','storage','gpu','psu']){const o=chosen(cat),row=el('div',null,'summary-item');row.append(el('span',t(cat)),el('span',o?`${quantity(state,o)} × ${o.sku}`:t('notSelected')));items.append(row);}const target=el('div');target.append(el('div',t('target')+': '+number(state.requirements.ramGB)+' GB RAM','target-note'));const meter=el('div',null,'meter'),fill=el('i');fill.style.width=Math.min(100,s.memory/state.requirements.ramGB*100)+'%';meter.append(fill);target.append(meter);items.append(target);const foot=el('div',null,'summary-footer');foot.append(el('div',t('partialCheck'),'summary-status'));if(state.step!==4)foot.append(arrowButton(t('continueReview'),()=>go(4)));else foot.append(btn(t('editBuild'),()=>go(3),'primary'));panel.append(head,metrics,items,foot);return panel;}
function reviewPage(root){root.append(leadBlock(t('reviewTitle'),t('reviewSub')));const values=stats(state,data),metrics=el('div',null,'review-metrics');for(const[v,u,l]of [[values.cores,'',t('physicalCores')],[values.memory,'GB',t('installedRAM')],[values.usable==null?'—':values.usable/1000,'TB',t('usableStorage')],[values.gpuMemory||'—','GB',t('gpuMemory')]]){const m=el('div',null,'review-metric');m.append(el('b',`${typeof v==='number'?number(v):v} ${u}`),el('small',l));metrics.append(m);}root.append(metrics);const grid=el('div',null,'review-grid'),left=el('div');grid.append(left,summaryPanel());const bom=el('div',null,'panel');bom.append(el('h2',t('bom')),el('p',model().name+' · '+state.chassis,'muted small'));const table=el('table'),head=el('tr');[t('category'),t('part'),t('sku'),t('qty')].forEach(x=>head.append(el('th',x)));table.append(head);const base=el('tr');[t('step2'),model().short,t('baseServer'),'1'].forEach(x=>base.append(el('td',x)));table.append(base);for(const o of selectedOptions(state,data)){const row=el('tr');row.append(el('td',t(o.category)),el('td',partTitle(o),'code'),el('td',o.sku,'code'),el('td',number(quantity(state,o)),'qty'));table.append(row);}const wrap=el('div',null,'table-scroll');wrap.append(table);bom.append(wrap,el('p',t('noPrice'),'small muted'));left.append(bom);const checks=el('div',null,'panel');checks.append(el('h2',t('requirementsCheck')));const missing=[];if(!chosen('cpu'))missing.push('missingCPU');if(!chosen('memory'))missing.push('missingMemory');if(!chosen('psu'))missing.push('missingPSU');if(!chosen('storage'))missing.push('missingStorage');if(state.model_id==='16913'&&!chosen('gpu'))missing.push('missingGPU');if(values.raidError)missing.push('invalidRaid');for(const key of missing)checks.append(checkRow(t('unknown'),t(key),'amber'));for(const x of directConflicts(state,data))checks.append(checkRow(t('conflict'),t(x.key==='gpuMemory'?'gpuMemoryTooLow':x.key),'red'));for(const r of activeFindings(state,data)){const row=checkRow(t(r.status==='conflict'?'conflict':'unknown'),ruleText(r),r.status==='conflict'?'red':'amber');row.append(evidence(r.evidence));checks.append(row);}checks.append(checkRow(t('unknown'),t('coverageNotice'),'amber'));left.append(checks,requirementsPanel());const fit=el('div',null,'panel');fit.append(el('h2',t('workloadFit')));for(const[actual,target,key]of [[values.memory,state.requirements.ramGB,'ramBelow'],[values.cores,state.requirements.cores,'coresBelow'],[values.usable==null?0:values.usable/1000,state.requirements.storageTB,'storageBelow']])fit.append(checkRow(actual>=target?'✓':t('unknown'),actual>=target?`${t(key==='ramBelow'?'installedRAM':key==='coresBelow'?'physicalCores':'usableStorage')}: ${number(actual)} / ${number(target)}`:t(key),actual>=target?'blue':'amber'));fit.append(el('p',guidance(),'small muted'));left.append(fit);const notes=el('div',null,'panel');notes.append(el('h2',t('technicalNotes')));[t('raidDisclaimer'),t('powerDisclaimer'),t('memorySpeedNote'),t('reviewSummary')].forEach(x=>notes.append(el('p',x,'small muted')));left.append(notes);const output=el('div',null,'panel');output.append(el('h2',t('output')));const buttons=el('div',null,'row wrap');buttons.append(btn(t('downloadBOM'),exportCSV,'primary'),btn(t('downloadJSON'),exportJSON),btn(t('print'),()=>window.print()));output.append(buttons);left.append(output);root.append(grid);}
function checkRow(label,text,color){const d=el('div',null,'check-row');d.append(el('span',label,'chip '+color),document.createTextNode(text));return d;}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('exported'));}
function exportJSON(){download(`ARIA-${model().short.replaceAll(' ','-')}.json`,JSON.stringify({configuration:state,catalog_version:data.version,status:'technical_review_required',calculations:stats(state,data),findings:activeFindings(state,data).map(r=>({id:r.id,status:r.status,message:r.message,evidence:r.evidence})),coverage:data.coverage},null,2),'application/json');}
function exportCSV(){const safe=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[[t('category'),t('part'),t('sku'),t('qty'),t('assurance')],[t('step2'),model().name,'CHASSIS SKU TO BE VERIFIED',1,t('reviewRequired')],...selectedOptions(state,data).map(o=>[t(o.category),partTitle(o),o.sku,quantity(state,o),t('reviewRequired')])];download('ARIA-HPE-BOM.csv','\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function render(){const root=layout();if(state.step===1)workPage(root);if(state.step===2)serversPage(root);if(state.step===3)componentPage(root);if(state.step===4)reviewPage(root);const footer=document.querySelector('footer'),links=el('span',null,'row');const c=el('button',t('allSources'),'info-link');c.onclick=coverageModal;links.append(c);const reset=el('button',t('reset'),'info-link');reset.onclick=()=>{if(confirm(t('confirmReset'))){state=initial();category='cpu';render();}};links.append(reset);footer.append(links);}
async function start(){try{const response=await fetch('./catalog.json');if(!response.ok)throw Error('Catalog unavailable');data=await response.json();render();}catch(e){app.replaceChildren(el('p',t('loadFailed'),'loading'),btn(t('retry'),start));}}
start();
